  1678→/**
  1679→ * Count task completions by scanning events for tool calls that invoke
  1680→ * `kspec task complete` or `npm run dev -- task complete`.
  1681→ *
  1682→ * Handles multiple adapter formats:
  1683→ * - claude-code-acp: rawInput.command is a string in tool_call_update events
  1684→ * - claude-agent-acp: rawInput.command is a string in tool_call_update events
  1685→ *   (initial tool_call event has empty rawInput {})
  1686→ * - codex-acp: rawInput.command is an array ['/usr/bin/bash', '-lc', 'kspec task complete @ref']
  1687→ *   in tool_call events; actual command is at index 2
  1688→ *
  1689→ * We use a fast substring check before JSON parsing for performance.
  1690→ */
  1691→async function countTaskCompletions(
  1692→  specDir: string,
  1693→  sessionId: string,
  1694→): Promise<number> {
  1695→  const eventsPath = getSessionEventsPath(specDir, sessionId);
  1696→  try {
  1697→    const content = await fsPromises.readFile(eventsPath, "utf-8");
  1698→    if (!content.trim()) return 0;
  1699→    const lines = content.trim().split("\n");
  1700→    let count = 0;
  1701→    for (const line of lines) {
  1702→      // Quick substring pre-filter: only parse lines that might contain task complete commands
  1703→      if (!line.includes("task complete")) continue;
  1704→      try {
  1705→        const event = JSON.parse(line);
  1706→        const rawCommand = event?.data?.update?.rawInput?.command;
  1707→        // Normalize: string (claude-*-acp) or array like [bash, -lc, cmd] (codex-acp)
  1708→        const command =
  1709→          typeof rawCommand === "string"
  1710→            ? rawCommand
  1711→            : Array.isArray(rawCommand) && rawCommand.length > 0
  1712→              ? rawCommand[rawCommand.length - 1]
  1713→              : undefined;
  1714→        if (typeof command === "string" && /\btask complete\b/.test(command)) {
  1715→          count++;
  1716→        }
  1717→      } catch {
  1718→        // Skip unparseable lines
  1719→      }
  1720→    }
  1721→    return count;
  1722→  } catch {
  1723→    return 0;
  1724→  }
  1725→}
